'use strict'
const { createSecureServer } = require('node:http2')
const { once } = require('node:events')
const { WebSocketServer, WebSocket: WSWebsocket } = require('ws')
const { key, cert } = require('@metcoder95/https-pem')
const { Agent, WebSocket, WebSocketStream } = require('../index.js')
const { uid } = require('../lib/web/websocket/constants')
const crypto = require('node:crypto')

async function main () {
  const server = createSecureServer({ cert, key, settings: { enableConnectProtocol: true } })
  const wsServer = new WebSocketServer({ noServer: true })

  server.on('stream', (stream, headers) => {
    stream.respond({
      ':status': 200,
      'sec-websocket-accept': crypto.hash('sha1', `${headers['sec-websocket-key']}${uid}`, 'base64')
    })
    const ws = new WSWebsocket(null, null, { autoPong: true })
    ws.setSocket(stream, Buffer.alloc(0), { maxPayload: 104857600, skipUTF8Validation: false })
    wsServer.emit('connection', ws, stream)
  })

  wsServer.on('connection', (ws) => {
    ws.on('message', (data, isBinary) => ws.send(data, { binary: isBinary }))
  })

  server.listen(0)
  await once(server, 'listening')
  const port = server.address().port

  const dispatcher = new Agent({ allowH2: true, connect: { rejectUnauthorized: false } })

  // scenario 1: WebSocketStream over h2
  const wss = new WebSocketStream(`wss://localhost:${port}`, { dispatcher })
  const { readable, writable } = await wss.opened
  console.log('WSS opened')
  const writer = writable.getWriter()
  await writer.write('hello')
  const reader = readable.getReader()
  console.log('read:', await reader.read())
  wss.close({ closeCode: 1000, reason: 'done' })
  console.log('closed:', await wss.closed)

  server.close()
  await dispatcher.close()
  await new Promise(r => wsServer.close(r))
}

main().catch(e => { console.error('ERR', e); process.exit(1) })
EOF
node .scratch/h2ws.js

