'use strict'
const { createSecureServer } = require('node:http2')
const { once } = require('node:events')
const { WebSocketServer, WebSocket: WSWebsocket } = require('ws')
const { key, cert } = require('@metcoder95/https-pem')
const { WebSocket, WebSocketStream } = require('../index.js')
const { uid } = require('../lib/web/websocket/constants')
const crypto = require('node:crypto')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')

async function main () {
  const certFile = path.join(os.tmpdir(), 'undici-scratch-ca.pem')
  fs.writeFileSync(certFile, cert)
  if (!process.env.NODE_EXTRA_CA_CERTS) {
    const { spawnSync } = require('node:child_process')
    const r = spawnSync(process.execPath, [__filename, ...process.argv.slice(2)], {
      stdio: 'inherit',
      env: { ...process.env, NODE_EXTRA_CA_CERTS: certFile }
    })
    console.log('child exit', r.status, r.signal)
    process.exit(r.status ?? 1)
  }

  const server = createSecureServer({ cert, key, settings: { enableConnectProtocol: true } })
  const wsServer = new WebSocketServer({ noServer: true })

  server.on('stream', (stream, headers) => {
    stream.respond({
      ':status': 200,
      'sec-websocket-accept': crypto.hash('sha1', `${headers['sec-websocket-key']}${uid}`, 'base64')
    })
    const ws = new WSWebsocket(null, null, { autoPong: true })
    ws.setSocket(stream, Buffer.alloc(0), { maxPayload: 104857600, skipUTF8Validation: false })
    wsServer.emit('connection', ws, stream)
  })

  wsServer.on('connection', (ws) => {
    ws.on('message', (data, isBinary) => ws.send(data, { binary: isBinary }))
  })

  server.listen(0)
  await once(server, 'listening')
  const port = server.address().port
  const url = 'wss://localhost:' + port

  const mode = process.argv[2] ?? 'ws'

  if (mode === 'ws') {
    const ws = new WebSocket(url)
    ws.binaryType = 'arraybuffer'
    await once(ws, 'open')
    console.log('WS opened')
    ws.send('hello')
    const [ev] = await once(ws, 'message')
    console.log('msg:', ev.data)
    ws.close(1000, 'done')
    const [close] = await once(ws, 'close')
    console.log('close:', close.code, close.reason, close.wasClean)
