'use strict'
// RFC 8441 compliant server: responds :status 200 with NO sec-websocket-accept,
// as browsers/wptserve do. Sec-WebSocket-Key/Accept are not used over HTTP/2.
const { createSecureServer } = require('node:http2')
const { once } = require('node:events')
const { WebSocketServer, WebSocket: WSWebsocket } = require('ws')
const { key, cert } = require('@metcoder95/https-pem')
const { WebSocket, WebSocketStream, Agent, setGlobalDispatcher } = require('../index.js')

setGlobalDispatcher(new Agent({ connect: { rejectUnauthorized: false } }))

async function main () {
  const server = createSecureServer({ cert, key, settings: { enableConnectProtocol: true } })
  const wsServer = new WebSocketServer({ noServer: true })

  server.on('stream', (stream, headers) => {
    console.log('server request headers:', JSON.stringify(headers, null, 1))
    stream.respond({ ':status': 200 })
    const ws = new WSWebsocket(null, null, { autoPong: true })
    ws.setSocket(stream, Buffer.alloc(0), { maxPayload: 104857600, skipUTF8Validation: false })
    wsServer.emit('connection', ws, stream)
  })

  wsServer.on('connection', (ws) => {
    ws.on('message', (data, isBinary) => ws.send(data, { binary: isBinary }))
  })

  server.listen(0)
  await once(server, 'listening')
  const url = 'wss://localhost:' + server.address().port

  const mode = process.argv[2] ?? 'ws'

  if (mode === 'ws') {
    const ws = new WebSocket(url)
    ws.addEventListener('error', (e) => console.log('error event:', e.error?.message))
    await once(ws, 'open')
    console.log('WS opened')
    ws.send('hello')
    const [ev] = await once(ws, 'message')
    console.log('msg:', ev.data)
    ws.close(1000, 'done')
    const [close] = await once(ws, 'close')
    console.log('close:', close.code, JSON.stringify(close.reason), close.wasClean)
  } else {
    const wss = new WebSocketStream(url)
    const { readable, writable } = await wss.opened
    console.log('WSS opened')
    const writer = writable.getWriter()
    await writer.write('hello')
    const reader = readable.getReader()
    console.log('read:', await reader.read())
    wss.close({ closeCode: 1000, reason: 'done' })
    console.log('closed:', await wss.closed)
  }

  server.close()
  await new Promise(r => wsServer.close(r))
}

main().catch(e => { console.error('ERR', e.message); process.exit(1) })
setTimeout(() => { console.error('TIMEOUT'); process.exit(2) }, 10000).unref()

